import{_ as t,o as a,c as i,a4 as s}from"./chunks/framework.C7iBV1LP.js";const h=JSON.parse('{"title":"Dendritic Architecture 🌲","description":"","frontmatter":{},"headers":[],"relativePath":"guide/architecture.md","filePath":"guide/architecture.md"}'),o={name:"guide/architecture.md"};function n(r,e,l,d,c,u){return a(),i("div",null,[...e[0]||(e[0]=[s(`<h1 id="dendritic-architecture-🌲" tabindex="-1">Dendritic Architecture 🌲 <a class="header-anchor" href="#dendritic-architecture-🌲" aria-label="Permalink to &quot;Dendritic Architecture 🌲&quot;">​</a></h1><p>Solar uses a <strong>dendritic module pattern</strong> rather than monolithic configuration files. Modules act like branches and leaves on a tree, automatically discovering themselves based on their folder structure.</p><hr><h2 id="🏗️-the-3-tier-system" tabindex="-1">🏗️ The 3-Tier System <a class="header-anchor" href="#🏗️-the-3-tier-system" aria-label="Permalink to &quot;🏗️ The 3-Tier System&quot;">​</a></h2><p>Solar organizes configuration into three intuitive layers:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>solar/</span></span>
<span class="line"><span>├── modules/</span></span>
<span class="line"><span>│   ├── core/         # Tier 1: Foundation (Disko, Users, Boot, Security, Nix)</span></span>
<span class="line"><span>│   ├── platforms/    # Tier 2: Compositors &amp; Display Managers (Niri, SDDM, ReGreet)</span></span>
<span class="line"><span>│   ├── programs/     # Tier 2: User Tools (Ghostty, Helix, Browsers, Media)</span></span>
<span class="line"><span>│   ├── services/     # Tier 2: Daemons (Tailscale, Nginx, Syncthing, Factorio)</span></span>
<span class="line"><span>│   ├── suites/       # Tier 3: Workflow bundles (workstation, gaming, server)</span></span>
<span class="line"><span>│   └── hosts/        # Terminal Leaves: Concrete machine declarations</span></span></code></pre></div><h3 id="tier-1-core-foundation-modules-core" tabindex="-1">Tier 1: Core Foundation (<code>modules/core/</code>) <a class="header-anchor" href="#tier-1-core-foundation-modules-core" aria-label="Permalink to &quot;Tier 1: Core Foundation (\`modules/core/\`)&quot;">​</a></h3><p>Provides essential host functionality:</p><ul><li><strong><code>system</code></strong>: Disko declarative storage, users, preservation, and virtualization.</li><li><strong><code>boot</code></strong>: UEFI Limine bootloader, kernel parameters, Secure Boot signing.</li><li><strong><code>security</code></strong>: AppArmor MAC profiles, kernel hardening, SSH, Agenix secrets.</li><li><strong><code>shell</code></strong>: Zsh, Starship prompt, Fastfetch, and core CLI utilities.</li><li><strong><code>nix</code></strong>: Lix package manager, automated GC, flake registry pinning.</li></ul><h3 id="tier-2-granular-feature-leaves" tabindex="-1">Tier 2: Granular Feature Leaves <a class="header-anchor" href="#tier-2-granular-feature-leaves" aria-label="Permalink to &quot;Tier 2: Granular Feature Leaves&quot;">​</a></h3><p>Individual tools and capabilities configured with typed options:</p><ul><li>Located under <code>platforms/</code>, <code>programs/</code>, <code>services/</code>, and <code>hardware/</code>.</li><li>Every feature defines an <code>enable = lib.mkEnableOption &quot;...&quot;</code> toggle under <code>myFeatures.&lt;path&gt;</code>.</li></ul><h3 id="tier-3-functional-suites-modules-suites" tabindex="-1">Tier 3: Functional Suites (<code>modules/suites/</code>) <a class="header-anchor" href="#tier-3-functional-suites-modules-suites" aria-label="Permalink to &quot;Tier 3: Functional Suites (\`modules/suites/\`)&quot;">​</a></h3><p>Convenient bundles that activate coherent groups of Tier 2 features:</p><ul><li><strong><code>suites.workstation.enable = true</code></strong>: Full graphical workstation environment (Niri, Ghostty, Firefox, Obsidian, Bitwarden, Sunshine).</li><li><strong><code>suites.server.enable = true</code></strong>: Headless server baseline (Fail2ban, key-only SSH, Tailscale, automated scrubs).</li><li><strong><code>suites.gaming.enable = true</code></strong>: Steam, Proton, Gamescope, OBS Studio, and performance governors.</li></ul><hr><h2 id="🔍-the-dendritic-autoscanner-modules-default-nix" tabindex="-1">🔍 The Dendritic Autoscanner (<code>modules/default.nix</code>) <a class="header-anchor" href="#🔍-the-dendritic-autoscanner-modules-default-nix" aria-label="Permalink to &quot;🔍 The Dendritic Autoscanner (\`modules/default.nix\`)&quot;">​</a></h2><p>Traditional Nix configs require maintaining massive <code>imports = [ ... ]</code> arrays in <code>flake.nix</code>. Solar eliminates this through automatic filesystem reflection:</p><div class="language-nix vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">nix</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># modules/default.nix</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Recursively traverses modules/ and discovers all default.nix and *.nix files</span></span></code></pre></div><h3 id="how-option-paths-are-generated" tabindex="-1">How Option Paths are Generated <a class="header-anchor" href="#how-option-paths-are-generated" aria-label="Permalink to &quot;How Option Paths are Generated&quot;">​</a></h3><p>The path on disk maps 1:1 to the option hierarchy:</p><table tabindex="0"><thead><tr><th style="text-align:left;">File Location on Disk</th><th style="text-align:left;">Discovered Option Path</th></tr></thead><tbody><tr><td style="text-align:left;"><code>modules/programs/terminal/ghostty.nix</code></td><td style="text-align:left;"><code>myFeatures.programs.terminal.ghostty.enable</code></td></tr><tr><td style="text-align:left;"><code>modules/services/networking/tailscale.nix</code></td><td style="text-align:left;"><code>myFeatures.services.networking.tailscale.enable</code></td></tr><tr><td style="text-align:left;"><code>modules/platforms/desktops/niri.nix</code></td><td style="text-align:left;"><code>myFeatures.platforms.desktops.niri.enable</code></td></tr></tbody></table><p>To add a new tool or daemon, simply drop a <code>.nix</code> file into the appropriate directory. It is immediately available across all hosts without touching <code>flake.nix</code>.</p>`,23)])])}const m=t(o,[["render",n]]);export{h as __pageData,m as default};
